  function isQaShowcaseMode() {
    if (!isDemoMode()) return false;
    const params = new URLSearchParams(window.location.search);
    return ["qa", "showcase"].some((key) => ["1", "true", "yes"].includes(String(params.get(key) || "").toLowerCase()));
  }

