  function normalizeAuthSession(payload) {
    const user = payload.user || {};
    const userEmail = String(user.email ? user.email : "").toLowerCase();

    const expiresIn = Number(payload.expires_in || 3600);
    const profile = authProfileFromUser(user, userEmail);

    return {
      accessToken: payload.access_token,
      refreshToken: payload.refresh_token,
      expiresAt: Date.now() + expiresIn * 1000,
      email: userEmail,
      userId: profileText(user.id),
      role: normalizeDashboardRole(profile.role),
      profile
    };
  }

  async function signInOwner(email, password) {
    const payload = await supabaseAuthRequest("/auth/v1/token?grant_type=password", {
      method: "POST",
      body: JSON.stringify({ email, password })
    });

    return normalizeAuthSession(payload);
  }

  async function refreshSession(session) {
    if (!session || !session.refreshToken) {
      return null;
    }

    const payload = await supabaseAuthRequest("/auth/v1/token?grant_type=refresh_token", {
      method: "POST",
      body: JSON.stringify({ refresh_token: session.refreshToken })
    });

    return normalizeAuthSession(payload);
  }

  async function verifySession(session) {
    if (!session || !session.accessToken) {
      return null;
    }

    if (Date.now() > Number(session.expiresAt || 0) - 60000) {
      const refreshed = await refreshSession(session);
      if (!refreshed || !refreshed.accessToken) {
        throw new Error("Please sign in again.");
      }
      return refreshed;
    }

    const payload = await supabaseAuthRequest("/auth/v1/user", {
      method: "GET",
      headers: { "Content-Type": "application/json" }
    }, session.accessToken);

    const userEmail = String(payload.email || "").toLowerCase();
    const profile = authProfileFromUser(payload, userEmail);

    return {
      ...session,
      email: userEmail,
      userId: profileText(payload.id || session.userId),
      role: normalizeDashboardRole(session.role || profile.role),
      profile
    };
  }

  async function signOutOwner() {
    const session = getSession();
    if (session && session.accessToken && isSupabaseConfigured()) {
      try {
        await supabaseAuthRequest("/auth/v1/logout", { method: "POST" }, session.accessToken);
      } catch (error) {
        // Local session cleanup should still happen if the remote token is already expired.
      }
    }

    clearSession();
  }

  function dashboardModuleDescriptors() {
    return [
      {
        key: "submissions",
        name: "quote submissions",
        loader: ({ signal } = {}) => supabaseRestRequest(`quote_submissions?select=${SUBMISSION_LIST_SELECT}&limit=80`, { method: "GET", signal }),
        fallback: [],
        normalize: (rows) => rows.map(normalizeSubmission).sort((a, b) => String(b.createdAtRaw || "").localeCompare(String(a.createdAtRaw || "")))
      },
      {
        key: "contacts",
        name: "contacts",
        loader: ({ signal } = {}) => supabaseRestRequest(`contacts?select=${CONTACT_LIST_SELECT}&limit=100`, { method: "GET", signal }),
        fallback: [],
        normalize: (rows) => rows.map(normalizeContact).sort((a, b) => String(b.createdAtRaw || "").localeCompare(String(a.createdAtRaw || "")))
      },
      {
        key: "jobs",
        name: "scheduled jobs",
        loader: ({ signal } = {}) => supabaseRestRequest(`scheduled_jobs?select=${JOB_LIST_SELECT}&limit=100`, { method: "GET", signal }),
        fallback: [],
        normalize: (rows) => rows.map(normalizeJob).sort((a, b) => String(a.dateRaw || "").localeCompare(String(b.dateRaw || "")))
      },
      { key: "tickets", name: "canonical tickets", loader: loadCanonicalTickets, fallback: [] },
      { key: "ticketEvents", name: "canonical ticket events", loader: loadCanonicalTicketEvents, fallback: [] },
      { key: "connectedOps", name: "ticket operations", loader: loadConnectedOperations, fallback: normalizeConnectedOpsBundle },
      { key: "ticketRelations", name: "ticket assignments", loader: loadTicketOperationalRelations, fallback: () => ({ crew: [], equipment: [] }) },
      {
        key: "notes",
        name: "job notes",
        loader: ({ signal } = {}) => supabaseRestRequest("job_notes?select=*&limit=100", { method: "GET", signal }),
        fallback: [],
        normalize: (rows) => rows.map(normalizeNote).sort((a, b) => String(b.createdAtRaw || "").localeCompare(String(a.createdAtRaw || "")))
      },
      {
        key: "reminders",
        name: "follow-up reminders",
        loader: ({ signal } = {}) => supabaseRestRequest(`follow_up_reminders?select=${REMINDER_LIST_SELECT}&limit=80`, { method: "GET", signal }),
        fallback: [],
        normalize: (rows) => rows.map(normalizeReminder).sort((a, b) => String(a.dueRaw || "").localeCompare(String(b.dueRaw || "")))
      },
      { key: "documents", name: "documents", loader: loadSalesDocuments, fallback: [] },
      { key: "operations", name: "operations", loader: loadOperationsRecords, fallback: [] },
      { key: "outreachProspects", name: "outreach prospects", loader: loadOutreachProspects, fallback: [] },
      { key: "outreachCompanies", name: "outreach companies", loader: loadOutreachCompanies, fallback: [] },
      { key: "outreachProperties", name: "outreach properties", loader: loadOutreachProperties, fallback: [] },
      { key: "routeStops", name: "route planner", loader: loadRouteStops, fallback: [] },
      { key: "equipmentItems", name: "equipment", loader: loadEquipmentItems, fallback: [] },
      { key: "equipmentMaintenance", name: "equipment maintenance", loader: loadEquipmentMaintenance, fallback: [] },
      { key: "hardwareGuide", name: "hardware guide", loader: loadHardwareGuide, fallback: [] },
      { key: "groundskeeperAi", name: "Groundkeeper & Lawnmower Man AI", loader: loadGroundskeeperAi, fallback: emptyGroundskeeperAiBundle },
      { key: "documentation", name: "documentation", loader: loadDocumentation, fallback: () => normalizeDocumentationBundle() },
      {
        key: "importExport",
        name: "import/export",
        loader: loadImportExportCenter,
        fallback: () => ({ modules: [], limits: {}, history: { imports: [], exports: [], syncs: [], backups: [] }, google: { configured: false, connections: [] }, fallback: "Import & Export Center could not be loaded." })
      },
      { key: "budgets", name: "job budgets", loader: loadBudgets, fallback: emptyBudgetBundle },
      { key: "leadActivity", name: "call history", loader: loadLeadActivity, fallback: [] },
      { key: "userProfiles", name: "user profiles", loader: loadUserProfiles, fallback: [] },
      { key: "auditLogs", name: "audit logs", loader: loadAuditLogs, fallback: [] }
    ];
  }

  function dashboardAllModuleKeys() {
    return dashboardModuleDescriptors().map((module) => module.key);
  }

  function dashboardInitialModuleKeys(section = state.activeSection) {
    const normalized = normalizeDashboardSection(section);
    const keysBySection = {
      overview: ["tickets", "ticketEvents", "jobs", "notes", "documents", "connectedOps", "ticketRelations", "userProfiles"],
      tickets: ["tickets", "ticketEvents", "submissions", "jobs", "documents", "notes", "connectedOps", "ticketRelations", "userProfiles"],
      calendar: ["jobs", "tickets", "ticketEvents", "notes", "documents", "connectedOps", "ticketRelations", "equipmentItems", "userProfiles"],
      outreach: ["outreachProspects", "tickets", "submissions"],
      "call-queue": ["outreachProspects", "leadActivity", "tickets", "contacts"],
      contacts: ["contacts", "jobs", "documents", "routeStops", "reminders"],
      documents: ["documents", "tickets", "submissions"],
      settings: [],
      "route-planner": ["routeStops", "jobs"],
      equipment: ["equipmentItems", "equipmentMaintenance", "hardwareGuide"],
      documentation: ["documentation"],
      "groundskeeper-ai": ["groundskeeperAi"],
      "ai-memory": [],
      "import-export": ["importExport"]
    };
    const routeKeys = ticketDrawerRouteState().ticketId
      ? ["tickets", "ticketEvents", "submissions", "jobs", "documents", "documentation", "budgets", "userProfiles"]
      : [];
    return Array.from(new Set([...(keysBySection[normalized] || keysBySection.overview), ...routeKeys]));
  }

  async function loadDashboardData(options = {}) {
    if (isDemoMode() && state.data.submissions.length) {
      return state.data;
    }

    if (isDemoMode()) {
      state.documentsReady = true;
      state.operationsReady = true;
      state.outreachReady = true;
      state.outreachCompaniesReady = true;
      state.outreachPropertiesReady = true;
      state.routeStopsReady = true;
      state.equipmentReady = true;
      state.equipmentMaintenanceReady = true;
      state.hardwareGuideReady = true;
      state.ticketsReady = true;
      state.groundskeeperAiReady = true;
      state.documentationReady = true;
      state.importExportReady = true;
      state.budgetsReady = true;
      state.leadActivityReady = true;
      state.userProfilesReady = true;
      state.auditLogsReady = true;
      return demoDashboardData();
    }

    if (options.resetErrors !== false) state.moduleErrors = [];

    const hasExplicitKeys = Array.isArray(options.keys);
    const requestedKeys = new Set(hasExplicitKeys ? options.keys : dashboardAllModuleKeys());
    const descriptors = dashboardModuleDescriptors().filter((module) => requestedKeys.has(module.key));
    const nextData = options.merge === false ? demoDashboardData() : { ...state.data };
    const concurrency = Math.max(1, Number(options.concurrency || descriptors.length || 1));
    for (let index = 0; index < descriptors.length; index += concurrency) {
      const chunk = descriptors.slice(index, index + concurrency);
      await Promise.all(chunk.map(async (module) => {
        const value = await loadModule(module.name, module.loader, module.fallback, {
          phase: options.phase || "full",
          essential: Boolean(options.essential),
          timeoutMs: options.timeoutMs,
          recordErrors: options.recordErrors
        });
        nextData[module.key] = module.normalize ? module.normalize(value || []) : value;
      }));
    }

    return nextData;
  }

  function dashboardSectionLoadInfo(section) {
    const normalized = normalizeDashboardSection(section);
    if (!dashboardSectionLoadState.has(normalized)) {
      dashboardSectionLoadState.set(normalized, {
        status: "idle",
        error: "",
        startedAt: "",
        loadedAt: "",
        promise: null
      });
    }
    return dashboardSectionLoadState.get(normalized);
  }

  function shouldHydrateDashboardSection(section, options = {}) {
    if (isDemoMode()) return false;
    if (!els.appView || els.appView.hidden) return false;
    if (options.force) return true;
    const info = dashboardSectionLoadInfo(section);
    return info.status !== "loaded" && !info.promise;
  }

  function hydrateDashboardSection(section = state.activeSection, options = {}) {
    const normalized = normalizeDashboardSection(section);
    const info = dashboardSectionLoadInfo(normalized);
    if (isDemoMode()) return Promise.resolve(state.data);
    if (info.promise && !options.force) return info.promise;
    if (!shouldHydrateDashboardSection(normalized, options)) return Promise.resolve(state.data);

    const keys = dashboardInitialModuleKeys(normalized);
    const phase = options.phase || `section:${normalized}`;
    const errorStartIndex = state.moduleErrors.length;
    info.status = "loading";
    info.error = "";
    info.startedAt = new Date().toISOString();
    if (state.activeSection === normalized && options.renderLoading !== false) {
      Promise.resolve().then(() => render());
    }

    const promise = loadDashboardData({
      keys,
      phase,
      essential: false,
      merge: true,
      resetErrors: options.resetErrors === true,
      recordErrors: options.recordErrors,
      concurrency: options.concurrency || DASHBOARD_SECTION_LOAD_CONCURRENCY,
      timeoutMs: options.timeoutMs || DASHBOARD_SECTION_LOAD_TIMEOUT_MS
    }).then(async (nextData) => {
      state.data = nextData;
      const phaseErrors = state.moduleErrors.slice(errorStartIndex).filter((item) => item.phase === phase);
      info.status = phaseErrors.length ? "partial" : "loaded";
      info.error = phaseErrors.map((item) => `${item.name}: ${item.message}`).join("; ");
      info.loadedAt = new Date().toISOString();
      state.lastRefreshAt = info.loadedAt;
      if (!state.performance.initialDataLoadedAt) state.performance.initialDataLoadedAt = info.loadedAt;
      if (state.activeSection === normalized || options.render !== false) {
        await render();
      }
      applyDashboardSupportStatus();
      restoreTicketDrawerFromRoute();
      return state.data;
    }).catch(async (error) => {
      info.status = "failed";
      info.error = error.message || "This dashboard section could not load.";
      recordModuleError(`section:${normalized}`, error, { phase: options.phase || `section:${normalized}`, scope: "support" });
      if (state.activeSection === normalized) await render();
      applyDashboardSupportStatus();
      return state.data;
    }).finally(() => {
      info.promise = null;
    });

    info.promise = promise;
    return promise;
  }

  function queueDashboardSectionHydration(section = state.activeSection, options = {}) {
    if (!shouldHydrateDashboardSection(section, options)) return;
    Promise.resolve().then(() => hydrateDashboardSection(section, options));
  }

